package main

import (
	"context"
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/jackc/pgx/v5"
)

// ASK ENGINE V2: THE SCHEMA CATALOGUE (roadmap 6.8.3).
//
// The catalogue is what the language model reads: the analyst views of migration 017, their descriptions and their columns, generated by code from the
// database's own comments, never written by the model. A pinned snapshot (ask_engine_catalogue.golden.json) lets the validator and the prompt be tested
// without a database; a live spec compares the snapshot with the database, so a migration that changes a view or a description cannot go unnoticed.
//
// The fixed part of the prompt (askPromptRules) is identical for every question, so that the model server's prompt cache is reused (a repeated prompt
// start costs about 2 s on the CPU laptop against about 40 s cold; roadmap 6.8.13). Per-question material (the shortlist of views, the retrieved
// verified examples, the question) is appended after it and never edited into it.

//go:embed ask_engine_catalogue.golden.json
var askCatalogueGolden []byte

//go:embed ask_engine_examples.json
var askExamplesJSON []byte

type askColumn struct {
	Name        string `json:"name"`
	Type        string `json:"type"`
	Description string `json:"description"`
}

type askView struct {
	Name        string      `json:"name"`
	Description string      `json:"description"`
	Columns     []askColumn `json:"columns"`
}

type askCatalogue struct {
	Views []askView `json:"views"`
}

// askExample is a verified question and the SQL that answers it. Examples are retrieved for the model to imitate; the code never executes one as an
// answer. Every example must pass askValidate against the catalogue (a spec checks), and a live spec runs each one against the database.
type askExample struct {
	ID       string   `json:"id"`
	Question string   `json:"question"`
	Views    []string `json:"views"`
	Shape    string   `json:"shape"`
	SQL      string   `json:"sql"`
}

// askQuerier is what the loader needs from a connection or pool.
type askQuerier interface {
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
}

const askCatalogueQuery = `
SELECT c.relname::text, coalesce(obj_description(c.oid, 'pg_class'), ''), a.attname::text, format_type(a.atttypid, a.atttypmod), coalesce(col_description(c.oid, a.attnum), '')
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped
WHERE n.nspname = 'analyst' AND c.relkind = 'v'
ORDER BY c.relname, a.attnum`

// loadAskCatalogue reads the analyst views, their descriptions and their columns from the database. It fails when any view or column has no
// description, because the model must never guess what a column means.
func loadAskCatalogue(ctx context.Context, db askQuerier) (*askCatalogue, error) {
	rows, err := db.Query(ctx, askCatalogueQuery)
	if err != nil {
		return nil, fmt.Errorf("reading the analyst catalogue: %w", err)
	}
	defer rows.Close()
	cat := &askCatalogue{}
	for rows.Next() {
		var view, viewDesc, column, columnType, columnDesc string
		if err := rows.Scan(&view, &viewDesc, &column, &columnType, &columnDesc); err != nil {
			return nil, fmt.Errorf("reading the analyst catalogue: %w", err)
		}
		if len(cat.Views) == 0 || cat.Views[len(cat.Views)-1].Name != view {
			cat.Views = append(cat.Views, askView{Name: view, Description: viewDesc})
		}
		last := &cat.Views[len(cat.Views)-1]
		last.Columns = append(last.Columns, askColumn{Name: column, Type: columnType, Description: columnDesc})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("reading the analyst catalogue: %w", err)
	}
	if err := cat.Check(); err != nil {
		return nil, err
	}
	return cat, nil
}

// Check fails for an empty catalogue, a view or column without a description, or a duplicate name.
func (c *askCatalogue) Check() error {
	if c == nil || len(c.Views) == 0 {
		return fmt.Errorf("the analyst catalogue is empty")
	}
	seen := map[string]bool{}
	for _, v := range c.Views {
		if seen[v.Name] {
			return fmt.Errorf("the analyst view %s appears twice", v.Name)
		}
		seen[v.Name] = true
		if strings.TrimSpace(v.Description) == "" {
			return fmt.Errorf("the analyst view %s has no description", v.Name)
		}
		if len(v.Columns) == 0 {
			return fmt.Errorf("the analyst view %s has no columns", v.Name)
		}
		for _, col := range v.Columns {
			if strings.TrimSpace(col.Description) == "" {
				return fmt.Errorf("the column %s.%s has no description", v.Name, col.Name)
			}
		}
	}
	return nil
}

// askGoldenCatalogue parses the pinned snapshot.
func askGoldenCatalogue() (*askCatalogue, error) {
	cat := &askCatalogue{}
	if err := json.Unmarshal(askCatalogueGolden, cat); err != nil {
		return nil, fmt.Errorf("the pinned analyst catalogue is not valid: %w", err)
	}
	if err := cat.Check(); err != nil {
		return nil, err
	}
	return cat, nil
}

// askExamples parses the verified examples.
func askExamples() ([]askExample, error) {
	var out []askExample
	if err := json.Unmarshal(askExamplesJSON, &out); err != nil {
		return nil, fmt.Errorf("the verified examples are not valid: %w", err)
	}
	seen := map[string]bool{}
	for _, e := range out {
		if e.ID == "" || e.Question == "" || e.SQL == "" || len(e.Views) == 0 || seen[e.ID] {
			return nil, fmt.Errorf("the verified example %q is incomplete or repeated", e.ID)
		}
		seen[e.ID] = true
	}
	return out, nil
}

// JSON is the canonical snapshot text: stable order, indented, ending in a newline.
func (c *askCatalogue) JSON() ([]byte, error) {
	out, err := json.MarshalIndent(c, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(out, '\n'), nil
}

// View returns the named view or nil.
func (c *askCatalogue) View(name string) *askView {
	for i := range c.Views {
		if c.Views[i].Name == name {
			return &c.Views[i]
		}
	}
	return nil
}

// askPromptRules is the fixed start of the prompt. It is never edited per question: that keeps the model server's prompt cache hot.
const askPromptRules = `You write one PostgreSQL SELECT (a WITH is allowed) that answers the question, using only the relations listed below. Never write anything that changes data.
Rules:
- Use only the listed relations and their columns. Name relations without a schema. Times are UTC instants; the case clock is Asia/Karachi, so convert with AT TIME ZONE 'Asia/Karachi' for local times and write explicit dates, never CURRENT_DATE.
- Leave out services and hubs with is_service and is_hub when the question is about people. Name every number, date and condition the question gives.
- A recursive query must keep a depth column that starts at 1 and grows by 1, bounded in the recursive part by a literal (depth < 3 means three hops, at most 4 hops), keep the visited numbers in an array and test NOT x = ANY (path), and end with LIMIT.
- Name result columns so that they can be drawn: src and dst for a graph (add kind and weight if known); lat and lon for a map; lane, start and "end" for lanes; t and value for a series; label and value for a ranking.
- Keep the query short: the views already do the joins and exclusions.
- Return JSON {"answerable": boolean, "sql": string}. If the relations cannot answer the question, answerable is false and sql is empty.`

// Render writes the catalogue text for the named views (all when names is empty): name, description and columns with their types and meaning. It is
// compact on purpose; every token of it is paid for in latency on the CPU laptop.
func (c *askCatalogue) Render(names []string) string {
	want := map[string]bool{}
	for _, n := range names {
		want[n] = true
	}
	var b strings.Builder
	for _, v := range c.Views {
		if len(want) > 0 && !want[v.Name] {
			continue
		}
		fmt.Fprintf(&b, "- %s: %s\n", v.Name, v.Description)
		cols := make([]string, 0, len(v.Columns))
		for _, col := range v.Columns {
			cols = append(cols, fmt.Sprintf("%s %s (%s)", col.Name, askShortType(col.Type), col.Description))
		}
		fmt.Fprintf(&b, "  columns: %s\n", strings.Join(cols, "; "))
	}
	return b.String()
}

func askShortType(t string) string {
	switch {
	case strings.HasPrefix(t, "timestamp with time zone"):
		return "timestamptz"
	case t == "double precision":
		return "float8"
	case strings.HasPrefix(t, "character varying"):
		return "text"
	}
	return t
}

// RenderExamples writes the verified examples a question may imitate.
func askRenderExamples(examples []askExample) string {
	var b strings.Builder
	for _, e := range examples {
		fmt.Fprintf(&b, "Verified example. Question: %s\nSQL: %s\n", e.Question, strings.Join(strings.Fields(e.SQL), " "))
	}
	return b.String()
}

// askPrompt assembles the messages for one question: the fixed rules first, then the shortlisted views, then the examples. The question is the user
// turn. Nothing before the shortlist depends on the question.
func askPrompt(cat *askCatalogue, shortlist []string, examples []askExample) string {
	sort.Strings(shortlist)
	var b strings.Builder
	b.WriteString(askPromptRules)
	b.WriteString("\n\nRelations:\n")
	b.WriteString(cat.Render(shortlist))
	if len(examples) > 0 {
		b.WriteString("\n")
		b.WriteString(askRenderExamples(examples))
	}
	return b.String()
}

// askShape names the kind of result a column list describes (roadmap 6.8.5, appendix D.1). The interface draws the view that fits and always offers
// the table. The conventions are part of the prompt, so the model names the columns it wants drawn.
func askShape(columns []string, rows int) string {
	has := map[string]bool{}
	for _, c := range columns {
		has[strings.ToLower(c)] = true
	}
	switch {
	case has["src"] && has["dst"]:
		return "graph"
	case has["lane"] && has["start"] && has["end"]:
		return "lanes"
	case has["lat"] && has["lon"]:
		return "map"
	case has["t"] && has["value"]:
		return "series"
	case has["label"] && has["value"]:
		return "ranked"
	case len(columns) == 1 && rows == 1:
		return "scalar"
	}
	return "table"
}
